rate=22050
with wave.open(str(root/'assets/media/portfolio-chime.wav'),'wb') as w:
 w.setnchannels(1);w.setsampwidth(2);w.setframerate(rate)
 frames=[]
 for frequency in [261.63,329.63,392.0]:
  for i in range(int(rate*.65)):
   t=i/rate; envelope=min(t/.03,1)*max(0,1-t/.65)**2
   frames.append(struct.pack('<h',int(6500*envelope*math.sin(2*math.pi*frequency*t))))
  frames.extend([b'\0\0']*int(rate*.12))
 w.writeframes(b''.join(frames))
